-- =====================================================================
--  Prime Script — Contenu prêt à l'emploi (3/12) : Accroches sectorielles (3 par secteur × étape)
--
--  Ce fichier s'importe avec les autres fichiers de database/content/ :
--      php tools/import-content.php
--  (ou, en MySQL : mysql -u ... prime_script < database/content/content.sql
--   si ce fichier a été concaténé dans content.sql).
--
--  Format d'une ligne de contenu (JSON, une ligne par enregistrement) :
--    {"code": "...", "type": "...", "sector": "...", "stage": "...",
--     "service": "...", "title": "...", "position": 10, "content": "<p>…</p>"}
--
--    code     identifiant stable du bloc (réimport = mise à jour, jamais de doublon)
--    type     presentation | accroche | barrage | repondeur | decouverte |
--             argumentaire | preuve | tarif | appel_action | conclusion
--    sector   slug du secteur (architectes, artisans-btp, restauration, services-b2b)
--    stage    slug de l'étape (premier-appel, relance, closing)
--    service  slug du service (site-web, application, automatisation-ia, chatbot-ia)
--    content  HTML simple : <p>, <ul>, <li>, <strong>, <em>
--
--  Convention d'écriture : le texte à dire est en clair, l'aide au commercial
--  est sur une ligne « Conseil : … » en italique (<p><em>Conseil : …</em></p>).
-- =====================================================================

SET NAMES utf8mb4;

{"code": "acc-architectes-premier-appel-1", "type": "accroche", "sector": "architectes", "stage": "premier-appel", "title": "Le carnet de commandes invisible", "position": 10, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nLa plupart des agences qu'on rencontre ont beaucoup de bouche-à-oreille, mais presque rien de visible en ligne. C'est aussi votre cas ?\n<br><em>Conseil : la question fermée en fin de phrase ouvre la conversation sans mettre la pression.</em>"}
{"code": "acc-architectes-premier-appel-2", "type": "accroche", "sector": "architectes", "stage": "premier-appel", "title": "La question des projets", "position": 20, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nQuand un client potentiel a vu une de vos réalisations, comment il vous contacte ensuite ?\n<br><em>Conseil : écoutez la réponse jusqu'au bout. Elle révèle souvent un PDF envoyé par mail, ou une page Instagram.</em>"}
{"code": "acc-architectes-premier-appel-3", "type": "accroche", "sector": "architectes", "stage": "premier-appel", "title": "Le temps sur les dossiers", "position": 30, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nCombien de temps passez-vous par semaine à chercher un plan, un devis ou un document de dossier ?\n<br><em>Conseil : si la réponse est « trop », ne cherchez pas le chiffre exact. Notez « trop » et avancez.</em>"}
{"code": "acc-architectes-relance-1", "type": "accroche", "sector": "architectes", "stage": "relance", "title": "La relance sur les projets", "position": 10, "content": "{contact}, bonjour, {prenom_commercial} de Prime Vision Solutions.\n\nJe vous avais parlé de la page qui présenterait vos projets. Est-ce que c'est toujours quelque chose que vous voulez montrer ?\n<br><em>Conseil : posez la question au présent. « Voulez-vous » engage plus que « voudriez-vous ».</em>"}
{"code": "acc-architectes-relance-2", "type": "accroche", "sector": "architectes", "stage": "relance", "title": "La relance par les photos", "position": 20, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nUne question simple : vos plus belles réalisations, elles sont où aujourd'hui ? Sur votre téléphone, dans un disque dur ?\n<br><em>Conseil : la réponse est souvent « un peu partout ». C'est exactement le problème à nommer.</em>"}
{"code": "acc-architectes-relance-3", "type": "accroche", "sector": "architectes", "stage": "relance", "title": "La relance sur la maquette", "position": 30, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nAvez-vous eu le temps de regarder la maquette que je vous ai envoyée ? Je peux passer en agence si c'est plus simple.\n<br><em>Conseil : une visite de vingt minutes vaut mieux que trois mails. Proposez-la sans hésiter.</em>"}
{"code": "acc-architectes-closing-1", "type": "accroche", "sector": "architectes", "stage": "closing", "title": "La date de démarrage", "position": 10, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nTout est validé côté contenu. Il ne reste que la date : on démarre avant ou après votre prochaine livraison de chantier ?\n<br><em>Conseil : un architecte pense en projets. Ancrez la date sur son calendrier de chantier, pas sur le vôtre.</em>"}
{"code": "acc-architectes-closing-2", "type": "accroche", "sector": "architectes", "stage": "closing", "title": "Les deux points restants", "position": 20, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nIl restait deux points : le budget de la galerie photo et le choix de la langue du site. On les tranche maintenant ?\n<br><em>Conseil : nommez les deux points avant d'appeler. Un client qui sait ce qui reste décide plus vite.</em>"}
{"code": "acc-architectes-closing-3", "type": "accroche", "sector": "architectes", "stage": "closing", "title": "La signature du devis", "position": 30, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nLe devis est finalisé. Je vous l'envoie à signer aujourd'hui, ou vous préférez en parler une dernière fois avec votre associé ?\n<br><em>Conseil : laissez toujours la porte de l'associé ouverte. Forcer une signature crée un regret.</em>"}
{"code": "acc-artisans-btp-premier-appel-1", "type": "accroche", "sector": "artisans-btp", "stage": "premier-appel", "title": "Les demandes perdues", "position": 10, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nBeaucoup d'artisans reçoivent leurs demandes sur le chantier, et certaines se perdent. Ça vous arrive aussi ?\n<br><em>Conseil : « ça vous arrive aussi » normalise le problème. Personne n'aime être le seul à mal s'organiser.</em>"}
{"code": "acc-artisans-btp-premier-appel-2", "type": "accroche", "sector": "artisans-btp", "stage": "premier-appel", "title": "Les concurrents en premier", "position": 20, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nQuand un particulier cherche votre métier dans votre ville, il tombe souvent sur ceux qui ont un site à jour. Vous avez un site, vous ?\n<br><em>Conseil : ne dites jamais « vous n'avez pas de site ». Demandez. La réponse appartient au client.</em>"}
{"code": "acc-artisans-btp-premier-appel-3", "type": "accroche", "sector": "artisans-btp", "stage": "premier-appel", "title": "Le devis qui traîne", "position": 30, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nVous faites combien de devis par semaine, et combien vous arrive à relancer vraiment ?\n<br><em>Conseil : la deuxième partie de la question est la plus importante. C'est là que se trouve l'argent perdu.</em>"}
{"code": "acc-artisans-btp-relance-1", "type": "accroche", "sector": "artisans-btp", "stage": "relance", "title": "La relance sur le devis", "position": 10, "content": "{contact}, bonjour, {prenom_commercial} de Prime Vision Solutions.\n\nJe vous avais envoyé le devis la semaine dernière. Vous avez eu le temps d'y jeter un œil ?\n<br><em>Conseil : posez la question au passé (« avez-vous eu le temps ») plutôt qu'au futur. C'est plus poli et plus direct.</em>"}
{"code": "acc-artisans-btp-relance-2", "type": "accroche", "sector": "artisans-btp", "stage": "relance", "title": "La relance sur la période", "position": 20, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nVous m'aviez dit que c'était chargé en ce moment. Est-ce que la période se calme un peu ?\n<br><em>Conseil : se souvenir d'une contrainte réelle vaut mille arguments. C'est ça, la relance utile.</em>"}
{"code": "acc-artisans-btp-relance-3", "type": "accroche", "sector": "artisans-btp", "stage": "relance", "title": "La relance par les photos", "position": 30, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nJe repense à vos chantiers. Vous avez des photos avant / après ? C'est ce qui rassure le plus un particulier.\n<br><em>Conseil : si la réponse est oui, proposez de les récupérer par téléphone dès aujourd'hui.</em>"}
{"code": "acc-artisans-btp-closing-1", "type": "accroche", "sector": "artisans-btp", "stage": "closing", "title": "La date et le paiement", "position": 10, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nLe devis est prêt. On démarre la semaine prochaine, et le paiement peut se faire en trois fois. Ça vous convient ?\n<br><em>Conseil : annoncez le paiement en plusieurs fois comme une évidence, pas comme une faveur.</em>"}
{"code": "acc-artisans-btp-closing-2", "type": "accroche", "sector": "artisans-btp", "stage": "closing", "title": "Le récapitulatif", "position": 20, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nJe récapitule : un site avec vos chantiers, un formulaire de devis, et les relances automatiques. Pour le prix du devis. C'est bien ce qu'il vous faut ?\n<br><em>Conseil : si le client corrige un point, c'est bon signe. Il s'approprie le projet.</em>"}
{"code": "acc-artisans-btp-closing-3", "type": "accroche", "sector": "artisans-btp", "stage": "closing", "title": "La dernière hésitation", "position": 30, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nQu'est-ce qui vous ferait hésiter encore, à ce stade ? Franchement.\n<br><em>Conseil : « franchement » autorise la vraie réponse. Sans ce mot, vous n'aurez que la réponse polie.</em>"}
{"code": "acc-restauration-premier-appel-1", "type": "accroche", "sector": "restauration", "stage": "premier-appel", "title": "Les appels pendant le service", "position": 10, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nVous recevez beaucoup d'appels pour des questions simples : horaires, carte, groupes ?\n<br><em>Conseil : à midi, soyez bref. Si la personne est en service, demandez l'heure du rappel immédiatement.</em>"}
{"code": "acc-restauration-premier-appel-2", "type": "accroche", "sector": "restauration", "stage": "premier-appel", "title": "La réservation du soir", "position": 20, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nDe plus en plus de clients réservent le soir, depuis leur téléphone. Chez vous, la réservation se fait comment aujourd'hui ?\n<br><em>Conseil : le restaurant est un des rares métiers où le client décide en dehors des heures d'ouverture.</em>"}
{"code": "acc-restauration-premier-appel-3", "type": "accroche", "sector": "restauration", "stage": "premier-appel", "title": "La carte en ligne", "position": 30, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nQuand vous changez la carte, elle est à jour en ligne dans la journée, ou ça prend plus de temps ?\n<br><em>Conseil : c'est une des rares douleurs que le restaurateur reconnaît immédiatement.</em>"}
{"code": "acc-restauration-relance-1", "type": "accroche", "sector": "restauration", "stage": "relance", "title": "La relance sur la réservation", "position": 10, "content": "{contact}, bonjour, {prenom_commercial} de Prime Vision Solutions.\n\nJe vous avais parlé de la réservation en ligne. Vous avez pu y réfléchir, ou la période ne s'y prête pas ?\n<br><em>Conseil : proposer « la période ne s'y prête pas » donne une sortie honorable. Beaucoup l'acceptent et reviennent.</em>"}
{"code": "acc-restauration-relance-2", "type": "accroche", "sector": "restauration", "stage": "relance", "title": "La relance par la carte", "position": 20, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nUne idée simple pour commencer : juste la carte et les horaires à jour, sans tout refaire. Ça vous intéresse ?\n<br><em>Conseil : un petit périmètre fait démarrer plus de projets qu'un grand devis. On agrandit ensuite.</em>"}
{"code": "acc-restauration-relance-3", "type": "accroche", "sector": "restauration", "stage": "relance", "title": "La relance après la carte", "position": 30, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nVous m'aviez dit que la nouvelle carte arrivait bientôt. Elle est sortie ?\n<br><em>Conseil : s'appuyer sur un événement réel du restaurant (nouvelle carte, terrasse, saison) rend l'appel naturel.</em>"}
{"code": "acc-restauration-closing-1", "type": "accroche", "sector": "restauration", "stage": "closing", "title": "La mise en ligne", "position": 10, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nLe site est prêt. On met en ligne avant ou après votre prochaine carte ?\n<br><em>Conseil : pour un restaurant, le calendrier des cartes est le vrai calendrier du projet.</em>"}
{"code": "acc-restauration-closing-2", "type": "accroche", "sector": "restauration", "stage": "closing", "title": "Les photos de plats", "position": 20, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nIl ne manque que les photos de plats. Vous les avez, ou on prend une heure avec un photographe ?\n<br><em>Conseil : proposez toujours une solution simple. Une photo au téléphone bien cadrée vaut mieux qu'un report.</em>"}
{"code": "acc-restauration-closing-3", "type": "accroche", "sector": "restauration", "stage": "closing", "title": "La décision", "position": 30, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nTout est calé : le site, la réservation, le prix. Je vous envoie le devis à signer aujourd'hui ?\n<br><em>Conseil : le restaurateur décide vite quand tout est concret. Évitez les détails techniques à ce stade.</em>"}
{"code": "acc-services-b2b-premier-appel-1", "type": "accroche", "sector": "services-b2b", "stage": "premier-appel", "title": "Le pipeline invisible", "position": 10, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nLa plupart des entreprises de services qu'on accompagne savent qu'elles perdent des opportunités, mais pas où. Ça vous parle ?\n<br><em>Conseil : en B2B, parlez « d'opportunités » plutôt que de « demandes ». Le vocabulaire compte.</em>"}
{"code": "acc-services-b2b-premier-appel-2", "type": "accroche", "sector": "services-b2b", "stage": "premier-appel", "title": "Le temps commercial", "position": 20, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nVos commerciaux passent-ils du temps à faire du suivi administratif au lieu de vendre ?\n<br><em>Conseil : la question est fermée exprès. Un « oui » suffit à ouvrir tout le reste de l'appel.</em>"}
{"code": "acc-services-b2b-premier-appel-3", "type": "accroche", "sector": "services-b2b", "stage": "premier-appel", "title": "Le premier rendez-vous", "position": 30, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nCombien de rendez-vous qualifiés recevez-vous par mois, et d'où viennent-ils ?\n<br><em>Conseil : demandez toujours « d'où viennent-ils ». C'est là que se cache le vrai problème.</em>"}
{"code": "acc-services-b2b-relance-1", "type": "accroche", "sector": "services-b2b", "stage": "relance", "title": "La relance sur la proposition", "position": 10, "content": "{contact}, bonjour, {prenom_commercial} de Prime Vision Solutions.\n\nJe vous avais envoyé la proposition. Je peux vous en faire un résumé en deux minutes, si c'est plus rapide.\n<br><em>Conseil : offrir le résumé évite le « je n'ai pas eu le temps de lire ». C'est presque toujours la vraie raison.</em>"}
{"code": "acc-services-b2b-relance-2", "type": "accroche", "sector": "services-b2b", "stage": "relance", "title": "La relance sur le décideur", "position": 20, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nPour que le projet avance, il faudrait peut-être inclure la personne qui valide le budget. Vous voyez un créneau à trois ?\n<br><em>Conseil : ne dites jamais « votre associé ». Demandez « la personne qui valide le budget ».</em>"}
{"code": "acc-services-b2b-relance-3", "type": "accroche", "sector": "services-b2b", "stage": "relance", "title": "La relance par étape", "position": 30, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nOn pourrait démarrer par une seule partie : la page de prise de rendez-vous. Le reste attendrait le mois prochain. Ça vous aiderait ?\n<br><em>Conseil : découper un projet fait baisser le risque perçu. C'est souvent ce qui débloque un dossier.</em>"}
{"code": "acc-services-b2b-closing-1", "type": "accroche", "sector": "services-b2b", "stage": "closing", "title": "La décision finale", "position": 10, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nLe devis reprend le périmètre, le prix et le calendrier. Vous le signez cette semaine, ou il manque encore une information ?\n<br><em>Conseil : « ou il manque une information » permet au client de dire ce qui bloque vraiment.</em>"}
{"code": "acc-services-b2b-closing-2", "type": "accroche", "sector": "services-b2b", "stage": "closing", "title": "La validation à chaque étape", "position": 20, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nVous validez chaque étape avant la suivante. Donc rien ne vous engage au-delà de ce que vous avez vu. Ça vous rassure ?\n<br><em>Conseil : en B2B, le risque perçu est le premier frein. Parlez livraison par étapes avant le prix.</em>"}
{"code": "acc-services-b2b-closing-3", "type": "accroche", "sector": "services-b2b", "stage": "closing", "title": "La date de démarrage", "position": 30, "content": "Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nSi on signe cette semaine, on démarre lundi. Après, le prochain créneau est dans trois semaines. Vous préférez quoi ?\n<br><em>Conseil : un vrai créneau de disponibilité n'est pas une fausse urgence. Ne l'inventez jamais, vérifiez-le.</em>"}
